// Formatea el aviso. Solo llega aqui si la query devolvio al menos una fila,
// asi que no hace falta guardar: sin hallazgos, el workflow muere en el Postgres.
const filas = $input.all().map(i => i.json);

const linea = (f) => {
  const silencio = f.dias_en_silencio === null
    ? 'NUNCA ha capturado nada'
    : `${f.dias_en_silencio} dias sin leer (umbral ${f.umbral_dias})`;
  return `<tr>
    <td style="padding:6px 12px;border-bottom:1px solid #eee"><b>${f.fuente}</b></td>
    <td style="padding:6px 12px;border-bottom:1px solid #eee">${f.ultima_lectura || '-'}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #eee">${silencio}</td>
    <td style="padding:6px 12px;border-bottom:1px solid #eee">${f.eventos_en_tabla}</td>
  </tr>`;
};

const html = `
<p>Estos scrapers estan <b>habilitados</b> pero llevan sin leer nada de la web
mas tiempo del esperado. Terminan en <i>success</i>, asi que el ERROR WORKFLOW
no los detecta: probablemente el origen cambio el HTML y el parser saca 0 items.</p>
<table style="border-collapse:collapse;font-family:sans-serif;font-size:14px">
  <tr style="background:#f5f5f5">
    <th style="padding:6px 12px;text-align:left">Fuente</th>
    <th style="padding:6px 12px;text-align:left">Ultima lectura</th>
    <th style="padding:6px 12px;text-align:left">Silencio</th>
    <th style="padding:6px 12px;text-align:left">Eventos en tabla</th>
  </tr>
  ${filas.map(linea).join('\n')}
</table>
<p style="color:#666;font-size:12px">Para silenciar una fuente: habilitado = false
en promotores_configuracion.</p>`;

return [{
  json: {
    emailSubject: `[C15] ${filas.length} scraper(s) sin capturar datos`,
    emailBodyHtml: html,
  }
}];
